import{_ as s,c as a,o as t,ae as i}from"./chunks/framework.70bNUV4I.js";const g=JSON.parse('{"title":"Editor Console","description":"","frontmatter":{},"headers":[],"relativePath":"samples/Editor/console.md","filePath":"samples/Editor/console.md"}'),n={name:"samples/Editor/console.md"};function o(l,e,p,d,c,r){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="editor-console" tabindex="-1">Editor Console <a class="header-anchor" href="#editor-console" aria-label="Permalink to &quot;Editor Console&quot;">​</a></h1><p>The Editor Console is a simple, built-in tool that shows engine/runtime logs and lets you execute engine commands at runtime. Open it from the Editor menu: Window → Console. The console is intended for quick debugging, tweaking runtime settings, and running small commands while you iterate in the editor.</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li>Live engine logs (info, warnings, errors).</li><li>Command output (results of executed commands, info messages).</li></ul><h2 id="basic-usage" tabindex="-1">Basic usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic usage&quot;">​</a></h2><p>Below are the Editor&#39;s primary console commands and short descriptions. Use the commands exactly as shown (arguments are space-separated).</p><h3 id="system-runtime" tabindex="-1">System / runtime <a class="header-anchor" href="#system-runtime" aria-label="Permalink to &quot;System / runtime&quot;">​</a></h3><ul><li><p><code>sys_info</code><br> Print high-level system information (CPU, RAM, GPU, Vulkan versions, enabled engine features).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sys_info</span></span></code></pre></div></li><li><p><code>sys_fps_max [value]</code><br> Get or set the frame limit. Without arguments prints current limit. With a number sets the limit.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sys_fps_max 60</span></span></code></pre></div></li><li><p><code>sys_vsync [on|off|1|0|true|false]</code><br> Toggle or query VSync.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sys_vsync true</span></span></code></pre></div></li></ul><h3 id="editor-session" tabindex="-1">Editor / session <a class="header-anchor" href="#editor-session" aria-label="Permalink to &quot;Editor / session&quot;">​</a></h3><ul><li><p><code>quit</code><br> Quit the Editor.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>quit</span></span></code></pre></div></li></ul><h3 id="scene-management" tabindex="-1">Scene management <a class="header-anchor" href="#scene-management" aria-label="Permalink to &quot;Scene management&quot;">​</a></h3><ul><li><p><code>scene_load &lt;path&gt;</code><br> Load a scene (path relative to project).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scene_load Assets/Scenes/scene_main.json</span></span></code></pre></div></li><li><p><code>scene_list</code><br> List currently loaded scenes.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scene_list</span></span></code></pre></div></li><li><p><code>scene_reload</code><br> Reload the last loaded scene (useful for quick iteration).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scene_reload</span></span></code></pre></div></li></ul><h3 id="rendering-environment-runtime-render-toggles" tabindex="-1">Rendering / environment (runtime render toggles) <a class="header-anchor" href="#rendering-environment-runtime-render-toggles" aria-label="Permalink to &quot;Rendering / environment (runtime render toggles)&quot;">​</a></h3><ul><li><p><code>r_ps1_jitter [on|off]</code><br> Toggle PS1-style vertex jitter / snapping.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_ps1_jitter 1</span></span></code></pre></div></li><li><p><code>r_ps1_warp [on|off]</code><br> Toggle PS1 affine texture warping effect.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_ps1_warp true</span></span></code></pre></div></li><li><p><code>r_dither [on|off]</code><br> Toggle screen dithering.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_dither 0</span></span></code></pre></div></li><li><p><code>r_crt [on|off]</code><br> Toggle CRT-style artifacts.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_crt 1</span></span></code></pre></div></li><li><p><code>r_resolution_mode &lt;mode_index&gt;</code><br> Set the engine-resolution preset (see Display / Resolution docs for mode indices and descriptions).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_resolution_mode 2</span></span></code></pre></div></li><li><p><code>r_ambient &lt;r&gt; &lt;g&gt; &lt;b&gt; &lt;strength&gt;</code><br> Set ambient color and strength for the environment lighting (values are floats).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>r_ambient 0.2 0.2 0.25 0.8</span></span></code></pre></div></li></ul><h3 id="physics" tabindex="-1">Physics <a class="header-anchor" href="#physics" aria-label="Permalink to &quot;Physics&quot;">​</a></h3><ul><li><p><code>phys_debug [on|off]</code><br> Toggle physics debug visualization in the scene.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phys_debug 1</span></span></code></pre></div></li><li><p><code>phys_gravity &lt;x&gt; &lt;y&gt; &lt;z&gt;</code><br> Set the global gravity vector for the physics system.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phys_gravity 0 -9.81 0</span></span></code></pre></div></li><li><p><code>phys_steps &lt;n&gt;</code><br> Set the physics collision step count (affects simulation accuracy and CPU cost).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phys_steps 2</span></span></code></pre></div></li></ul>',16)])])}const u=s(n,[["render",o]]);export{g as __pageData,u as default};
